//! Oracle rows from Wine's `dlls/msado15/recordset.c` `parse_criteria`, compiled
//! verbatim under ASan and UBSan behind a small harness. The rows are generated by
//! `canon/msado15/gen.sh` from `rows.txt`; the harness source is `canon/msado15/harness.c`.
//! Every row ran clean, with no sanitizer report.

use crate::parse_criteria;

#[rustfmt::skip]
const VECTORS: &[(&str, &str)] = &[
    ("a=1", "ok|2|a|1"),
    ("[first name]=Bob", "ok|2|first name|Bob"),
    ("price<10", "ERR"),
    ("price<=10", "ok|2|price<|10"),
    ("price>=10", "ok|2|price>|10"),
    ("price>5", "ERR"),
    ("code<>7", "ERR"),
    ("name like Jo*", "ok|5|name|Jo"),
    ("name LIKE jo*", "ok|5|name|jo"),
    ("name like *ob*", "ok|6|name|ob"),
    ("title = 'it''s'", "ok|2|title|it's"),
    ("title = 'plain text'", "ok|2|title|plain text"),
    ("day = #2024-01-02#", "ok|2|day|2024-01-02"),
    ("flag = true   ", "ok|2|flag|true"),
    ("  name   =   'a b'  ", "ok|2|name|a b"),
    ("name = 'unterminated", "ok|2|name|unterminated"),
    ("name like 'ab*'", "ok|5|name|ab"),
    ("name like '*a''b*'", "ok|6|name|a'b"),
    ("a=1 b=2", "ERR"),
    ("name", "ERR"),
    ("name like *abc", "ERR"),
    ("name like *", "ERR"),
    ("=5", "ERR"),
    ("a=x'y", "ok|2|a|x'y"),
    ("[a]", "ERR"),
];

/// Runs one criterion through the port and formats it as the harness prints it.
pub(crate) fn replay(text: &str) -> String {
    let units: Vec<u16> = text.encode_utf16().collect();
    match parse_criteria(&units) {
        None => "ERR".to_string(),
        Some(c) => format!(
            "ok|{}|{}|{}",
            c.op.code(),
            String::from_utf16_lossy(&c.column),
            String::from_utf16_lossy(&c.value)
        ),
    }
}

#[test]
fn oracle_rows_match_wine() {
    for (input, expected) in VECTORS {
        assert_eq!(replay(input), *expected, "criteria {input:?}");
    }
}
